∀ (a : ↥Breakdown.Freq.L2C) {f : Breakdown.Space → Breakdown.Freq.CSpace}
  (hf : MeasureTheory.MemLp f 2 MeasureTheory.volume),
  ‖a - MeasureTheory.MemLp.toLp f hf‖ = (MeasureTheory.eLpNorm (fun ξ => ↑↑a ξ - f ξ) 2 MeasureTheory.volume).toReal

∀ (a : ↥Breakdown.Freq.L2C) {f : Breakdown.Space → Breakdown.Freq.CSpace}
  (hf : MeasureTheory.MemLp f 2 MeasureTheory.volume),
  ‖MeasureTheory.MemLp.toLp f hf - a‖ = (MeasureTheory.eLpNorm (fun ξ => f ξ - ↑↑a ξ) 2 MeasureTheory.volume).toReal

∀ {T : ↥Breakdown.Freq.L2C →L[ℝ] ↥Breakdown.Freq.L2C} {A : Breakdown.Space → Breakdown.Space}
  {F : Breakdown.Space → Breakdown.Freq.CSpace →L[ℝ] Breakdown.Freq.CSpace},
  Breakdown.Freq.IsRealizedBy T A F → Breakdown.Freq.fieldOp A F = T

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] (T : X →L[ℝ] X) (c : ℂ)
  (z : Breakdown.Spectral.Complexification X),
  { re := T (c • z).re, im := T (c • z).im } = (RingHom.id ℂ) c • { re := T z.re, im := T z.im }

∀ {E : Type u_1} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace ℝ E] {f : Breakdown.Space → E}
  {U : Set Breakdown.Space},
  IsOpen U → (∀ x ∈ U, f x = 0) → ∀ (v x : Breakdown.Space), x ∈ U → Breakdown.Freq.Internal.NiceApprox.pd v f x = 0

∀ {S T : ↥Breakdown.Freq.L2C →L[ℝ] ↥Breakdown.Freq.L2C} {A : Breakdown.Space → Breakdown.Space}
  {F : Breakdown.Space → Breakdown.Freq.CSpace →L[ℝ] Breakdown.Freq.CSpace},
  Breakdown.Freq.IsRealizedBy S A F → Breakdown.Freq.IsRealizedBy T A F → S = T

∀ {X : Type u_1} [inst : NormedAddCommGroup X] [inst_1 : InnerProductSpace ℝ X] (T : X →L[ℝ] X)
  (z w : Breakdown.Spectral.Complexification X),
  { re := T (z + w).re, im := T (z + w).im } = { re := T z.re, im := T z.im } + { re := T w.re, im := T w.im }

∀ (E : Breakdown.Space ≃L[ℝ] Breakdown.Space) {F : Breakdown.Space → Breakdown.Freq.CSpace →L[ℝ] Breakdown.Freq.CSpace}
  {C : ℝ} (hF : MeasureTheory.AEStronglyMeasurable F MeasureTheory.volume) (hC : ∀ (ξ : Breakdown.Space), ‖F ξ‖ ≤ C),
  Breakdown.Freq.IsRealizedBy (Breakdown.Freq.Internal.FieldOp.op E hF hC) (⇑E) F
